let students = context.get("students") || {};

let d = msg.payload;

// Ignore invalid message
if (!d || typeof d !== "object") {
    return null;
}

// Ignore EXIT BUTTON event
if (!d.uid || d.uid === "-" || d.student === "DOOR EXIT") {
    return null;
}

// Update student record
students[d.uid] = {
    uid: d.uid,
    student: d.student || "-",
    attendance: d.attendance || "-",
    entry: d.entry_time || "-",
    exit: d.exit_time || "-",
    duration: d.duration || "-"
};

context.set("students", students);

// Fixed student order
let order = [
    "432293a",
    "715bc517",
    "53364616"
];

// Create table data
let table = [];

for (let uid of order) {

    if (students[uid]) {

        table.push({
            student: students[uid].student,
            attendance: students[uid].attendance,
            entry: students[uid].entry,
            exit: students[uid].exit,
            duration: students[uid].duration
        });

    }
}

// Send array to Template
msg.payload = table;

return msg;

// ==========================================
// FTF CALCULATION
// MULTI-LAB VERSION
// ==========================================

// FTF requirement for every subject
const REQUIRED_FTF_HOURS = 80;


// ==========================================
// GET INCOMING ATTENDANCE RECORD
// ==========================================

let data = msg.payload;


// Check data
if (!data || typeof data !== "object") {
    return null;
}


// ==========================================
// REQUIRED DATA
// ==========================================

if (
    !data.uid ||
    !data.student ||
    !data.subject
) {

    node.warn(
        "INCOMPLETE ATTENDANCE DATA"
    );

    return null;
}


// ==========================================
// DURATION REQUIRED
// ==========================================

if (
    !data.duration ||
    data.duration === "-" ||
    data.duration === null
) {

    node.warn(
        "NO COMPLETED SESSION DURATION"
    );

    return null;
}


// ==========================================
// CREATE FTF STORAGE
// ==========================================

let ftfRecords =
    flow.get("ftfRecords") || {};


// ==========================================
// UNIQUE STUDENT + SUBJECT
// IMPORTANT:
// Student Detail uses uid_subject
// ==========================================

// ==========================================
// FTF KEY
// ONE STUDENT + ONE SUBJECT
// ==========================================

let key =
    data.uid +
    "_" +
    data.subject;


// ==========================================
// MIGRATE OLD MULTI-LAB KEY IF EXISTS
// ==========================================

let oldKey =
    data.uid +
    "_" +
    data.lab +
    "_" +
    data.subject;

if (
    !ftfRecords[key] &&
    ftfRecords[oldKey]
) {

    ftfRecords[key] =
        ftfRecords[oldKey];

    delete ftfRecords[oldKey];

    node.warn(
        "FTF OLD DATA MIGRATED | " +
        oldKey +
        " -> " +
        key
    );
}


// ==========================================
// CREATE RECORD
// ==========================================

if (!ftfRecords[key]) {

    ftfRecords[key] = {

        uid:
            data.uid,

        student:
            data.student,

        lab:
            data.lab || "",

        className:
            data.className || "",

        subject:
            data.subject,

        requiredHours:
            REQUIRED_FTF_HOURS,

        completedSeconds:
            0,

        completedHours:
            0,

        completedMinutes:
            0,

        remainingHours:
            REQUIRED_FTF_HOURS,

        remainingMinutes:
            0,

        status:
            "INCOMPLETE",

        notice:
            "FTF REQUIREMENT NOT YET COMPLETED",

        sessions:
            0,

        lastSession:
            null

    };

}


// ==========================================
// SESSION KEY
// Prevent duplicate FTF calculation
// ==========================================

let sessionKey =
    (data.date || "") +
    "_" +
    (data.entry_time || "") +
    "_" +
    (data.exit_time || "");


// ==========================================
// CHECK DUPLICATE SESSION
// ==========================================

if (
    ftfRecords[key].lastSession !==
    sessionKey
) {

    // --------------------------------------
    // Convert duration
    // --------------------------------------

    let parts =
        data.duration.split(":");


    if (parts.length === 3) {

        let hours =
            parseInt(parts[0]) || 0;

        let minutes =
            parseInt(parts[1]) || 0;

        let seconds =
            parseInt(parts[2]) || 0;


        let durationSeconds =
            (hours * 3600) +
            (minutes * 60) +
            seconds;


        // ----------------------------------
        // ADD FTF
        // ----------------------------------

        ftfRecords[key].completedSeconds +=
            durationSeconds;


        ftfRecords[key].sessions += 1;


        ftfRecords[key].lastSession =
            sessionKey;

    }

}


// ==========================================
// CALCULATE COMPLETED TIME
// ==========================================

let completedSeconds =
    ftfRecords[key].completedSeconds;


let requiredSeconds =
    REQUIRED_FTF_HOURS * 3600;


let remainingSeconds =
    requiredSeconds -
    completedSeconds;


if (remainingSeconds < 0) {

    remainingSeconds = 0;

}


// ==========================================
// COMPLETED
// ==========================================

ftfRecords[key].completedHours =
    Math.floor(
        completedSeconds / 3600
    );


ftfRecords[key].completedMinutes =
    Math.floor(
        (completedSeconds % 3600) / 60
    );


// ==========================================
// REMAINING
// ==========================================

ftfRecords[key].remainingHours =
    Math.floor(
        remainingSeconds / 3600
    );


ftfRecords[key].remainingMinutes =
    Math.floor(
        (remainingSeconds % 3600) / 60
    );


// ==========================================
// STATUS
// ==========================================

if (
    completedSeconds >=
    requiredSeconds
) {

    ftfRecords[key].status =
        "REQUIREMENT MET";

    ftfRecords[key].notice =
        "FTF REQUIREMENT COMPLETED";

}
else {

    ftfRecords[key].status =
        "INCOMPLETE";

    ftfRecords[key].notice =
        ftfRecords[key].remainingHours +
        " HOURS FTF REMAINING";

}


// ==========================================
// SAVE
// ==========================================

flow.set(
    "ftfRecords",
    ftfRecords
);


// ==========================================
// OUTPUT
// ==========================================

msg.payload =
    ftfRecords[key];

return msg;

// ==========================================
// CURRENT CLASS DETECTOR
// REAL TIME + AUTOMATIC TEST MODE
// ==========================================

let timetable = flow.get("masterTimetable") || [];

let now = new Date();

let dayNames = [
    "SUNDAY",
    "MONDAY",
    "TUESDAY",
    "WEDNESDAY",
    "THURSDAY",
    "FRIDAY",
    "SATURDAY"
];

let currentDay = dayNames[now.getDay()];

let testMode = flow.get("testMode") || false;


// ==========================================
// TIME FUNCTIONS
// ==========================================

function timeToMinutes(time) {

    let parts = time.split(":");

    return (
        parseInt(parts[0]) * 60 +
        parseInt(parts[1])
    );
}

function minutesToTime(minutes) {

    minutes = Math.floor(minutes);

    let hours = Math.floor(minutes / 60);

    let mins = minutes % 60;

    return (
        String(hours).padStart(2, "0") +
        ":" +
        String(mins).padStart(2, "0")
    );
}


// ==========================================
// TODAY'S SCHEDULE
// ==========================================

let todaySchedule = timetable
    .filter(function(item) {

        return item.day === currentDay;

    })
    .sort(function(a, b) {

        return (
            timeToMinutes(a.start) -
            timeToMinutes(b.start)
        );

    });


// ==========================================
// DETERMINE CURRENT TIME
// ==========================================

let currentMinutes;


// ==========================================
// NORMAL MODE
// ==========================================

if (!testMode) {

    currentMinutes =
        now.getHours() * 60 +
        now.getMinutes();

}


// ==========================================
// TEST MODE
// ==========================================

else {

    let testStartRealTime =
        flow.get("testStartRealTime");

    // Safety fallback
    if (!testStartRealTime) {

        testStartRealTime =
            Date.now();

        flow.set(
            "testStartRealTime",
            testStartRealTime
        );

    }


    // --------------------------------------
    // CHECK IF TODAY HAS CLASS
    // --------------------------------------

    if (todaySchedule.length > 0) {

        let earliestStart =
            timeToMinutes(
                todaySchedule[0].start
            );


        // Real elapsed time
        let elapsedMinutes =
            (Date.now() - testStartRealTime)
            / 60000;


        // Virtual time
        currentMinutes =
            earliestStart +
            elapsedMinutes;


        // ----------------------------------
        // LIMIT TO LAST CLASS END
        // ----------------------------------

        let lastEnd = 0;

        for (let item of todaySchedule) {

            let end =
                timeToMinutes(item.end);

            if (end > lastEnd) {

                lastEnd = end;

            }

        }

        if (currentMinutes > lastEnd) {

            currentMinutes = lastEnd;

        }

    }

    else {

        // No timetable today
        currentMinutes =
            now.getHours() * 60 +
            now.getMinutes();

    }

}


// ==========================================
// CURRENT ONGOING CLASSES
// ==========================================

let currentClasses = [];

for (let item of todaySchedule) {

    let startMinutes =
        timeToMinutes(item.start);

    let endMinutes =
        timeToMinutes(item.end);


    if (
        currentMinutes >= startMinutes &&
        currentMinutes < endMinutes
    ) {

        currentClasses.push({

            lab: item.lab,

            subject: item.subject,

            className: item.className,

            start: item.start,

            end: item.end,

            expectedStudents:
                item.expectedStudents,

            requiredFTF:
                item.requiredFTF,

            status: "ONGOING"

        });

    }

}


// ==========================================
// NEXT CLASSES
// ==========================================

let nextClasses = [];

for (let item of todaySchedule) {

    let startMinutes =
        timeToMinutes(item.start);


    if (startMinutes > currentMinutes) {

        nextClasses.push(item);

    }

}


// ==========================================
// SAVE CURRENT CLASSES
// ==========================================

flow.set(
    "currentClasses",
    currentClasses
);


// ==========================================
// OUTPUT
// ==========================================

msg.payload = {

    currentTime:
        minutesToTime(currentMinutes),

    currentDay:
        currentDay,

    testMode:
        testMode,

    currentClasses:
        currentClasses,

    nextClasses:
        nextClasses,

    todaySchedule:
        todaySchedule

};

return msg;

// ==========================================
// ATTENDANCE RECORD
// MULTI-LAB
// TEST MODE
// STUDENT CLASS VALIDATION
// ONGOING + OFFICIAL CLOCK-OUT
// + ATTENDANCE HISTORY STORAGE
// ==========================================

let currentClasses =
    flow.get("currentClasses") || [];

let data = msg.payload;

if (!data || typeof data !== "object") {
    return null;
}


// ==========================================
// CHECK RFID UID
// ==========================================

if (!data.uid || data.uid === "-") {

    node.warn("RFID UID NOT FOUND");

    return null;
}


// ==========================================
// GET LAB
// ==========================================

let lab =
    data.lab ||
    data.lab_id ||
    null;

if (!lab) {

    node.warn("LAB ID NOT FOUND");

    return null;
}


// ==========================================
// STUDENT DATABASE
// ==========================================

let students =
    flow.get("students") || [];

let studentRecord =
    students.find(function (student) {

        return String(student.uid || "").trim().toUpperCase() ===
       String(data.uid || "").trim().toUpperCase();

    });


// ==========================================
// STUDENT NOT REGISTERED
// ==========================================

if (!studentRecord) {

    node.warn(
        "RFID UID NOT REGISTERED: " +
        data.uid
    );

    return null;
}


// ==========================================
// STUDENT INFORMATION
// ==========================================

let uid =
    studentRecord.uid;

let student =
    studentRecord.name;

let studentClass =
    studentRecord.semester;

let studentStatus =
    studentRecord.status;


// ==========================================
// CHECK STUDENT STATUS
// ==========================================

if (studentStatus !== "ACTIVE") {

    node.warn(
        "STUDENT INACTIVE | " +
        student +
        " | STATUS = " +
        studentStatus
    );

    return null;
}


// ==========================================
// FIND CURRENT CLASS
// ==========================================

let normalizedLab = String(lab)
    .trim()
    .toUpperCase();

let currentClass =
    currentClasses.find(function (item) {
        return String(item.lab)
            .trim()
            .toUpperCase() === normalizedLab;
    });


// ==========================================
// TEST MODE
// ==========================================




// ==========================================
// ATTENDANCE STORAGE
// ==========================================

let attendance =
    flow.get("attendanceRecords") || {};

if (!attendance[uid]) {

    attendance[uid] = {};

}


// ==========================================
// HISTORY STORAGE
// ==========================================

let attendanceHistory =
    global.get("attendanceHistory") || [];


// ==========================================
// FUNCTION
// SAVE / UPDATE HISTORY RECORD
// ==========================================

function saveHistoryRecord(record, sessionKey) {

    if (
        !record ||
        !record.uid ||
        !sessionKey
    ) {
        return;
    }

    let historyKey =
        record.uid + "_" + sessionKey;

    let existingIndex =
        attendanceHistory.findIndex(function (item) {

            return item.historyKey === historyKey;

        });


    let historyRecord = {

        historyKey:
            historyKey,

        uid:
            record.uid,

        student:
            record.student || "",

        lab:
            record.lab || "",

        subject:
            record.subject || "",

        className:
            record.className || "",

        date:
            record.date || "",

        classStart:
            record.classStart || "",

        classEnd:
            record.classEnd || "",

        requiredFTF:
            record.requiredFTF || 0,

        entry_time:
            record.entry_time || "-",

        exit_time:
            record.exit_time || "-",

        duration:
            record.duration || "-",

        status:
            record.status || "ABSENT",

        reason:
            record.reason || "",

        otherReason:
            record.otherReason || ""

    };


    if (existingIndex >= 0) {

        attendanceHistory[existingIndex] =
            historyRecord;

    } else {

        attendanceHistory.push(
            historyRecord
        );

    }


    global.set(
        "attendanceHistory",
        attendanceHistory
    );
}


// ==========================================
// OFFICIAL CLOCK-OUT
// ESP32 sends event = EXIT
// ==========================================

if (data.event === "EXIT") {

    let studentRecords =
        attendance[uid];

    let activeRecord = null;

    let activeSessionKey = null;


    // --------------------------------------
    // FIND ACTIVE ATTENDANCE
    // --------------------------------------

    for (
        let sessionKey in studentRecords
    ) {

        let record =
            studentRecords[sessionKey];

        if (
            !record ||
            typeof record !== "object"
        ) {

            continue;

        }


        if (
            String(record.lab || "").trim().toUpperCase() ===
    String(lab || "").trim().toUpperCase() &&

String(record.uid || "").trim().toUpperCase() ===
    String(uid || "").trim().toUpperCase() &&
            record.status === "PRESENT" &&
            record.entry_time &&
            (
                !record.exit_time ||
                record.exit_time === "-"
            )
        ) {

            activeRecord = record;

            activeSessionKey =
                sessionKey;

            break;

        }

    }


    // --------------------------------------
    // NO ACTIVE RECORD
    // --------------------------------------

    if (!activeRecord) {

        node.warn(
            "NO ACTIVE ATTENDANCE RECORD FOR OFFICIAL EXIT | " +
            student
        );

        return null;

    }


    // --------------------------------------
    // TAKE OFFICIAL DATA FROM ESP32
    // --------------------------------------

    activeRecord.exit_time =
        data.exit_time ||
        activeRecord.exit_time;

    activeRecord.duration =
        data.duration ||
        activeRecord.duration;

    activeRecord.status =
        "PRESENT";


    // --------------------------------------
    // SAVE ATTENDANCE
    // --------------------------------------

    attendance[uid][activeSessionKey] =
        activeRecord;

    flow.set(
        "attendanceRecords",
        attendance
    );


    // --------------------------------------
    // SAVE TO HISTORY
    // --------------------------------------

    saveHistoryRecord(
        activeRecord,
        activeSessionKey
    );


    // --------------------------------------
    // SEND TO FTF CALCULATION
    // --------------------------------------

    msg.payload =
        activeRecord;

    return msg;
}


// ==========================================
// NO CURRENT CLASS
// AND NOT OFFICIAL EXIT
// ==========================================

if (!currentClass) {

    node.warn(
        "NO CURRENT CLASS FOR " +
        lab
    );

    return null;
}


// ==========================================
// CHECK STUDENT SEMESTER
// ==========================================

if (
    studentClass !==
    currentClass.className
) {

    node.warn(
        "CLASS MISMATCH | " +
        student +
        " = " +
        studentClass +
        " | CURRENT CLASS = " +
        currentClass.className
    );

    return null;
}


// ==========================================
// CURRENT DATE
// ==========================================

let now =
    new Date();

let dateString =
    now.getFullYear() +
    "-" +
    String(
        now.getMonth() + 1
    ).padStart(2, "0") +
    "-" +
    String(
        now.getDate()
    ).padStart(2, "0");


// ==========================================
// CURRENT TIME
// ==========================================

let currentTime =
    now.toLocaleTimeString(
        "en-MY",
        {
            hour12: false
        }
    );


// ==========================================
// SESSION KEY
// ==========================================

let sessionKey =
    dateString +
    "_" +
    lab +
    "_" +
    currentClass.subject +
    "_" +
    currentClass.className +
    "_" +
    currentClass.start +
    "_" +
    currentClass.end;


// ==========================================
// CREATE NEW ATTENDANCE RECORD
// ==========================================

if (
    !attendance[uid][sessionKey]
) {

    attendance[uid][sessionKey] = {

        uid: uid,

        student: student,

        lab: lab,

        className: studentClass,

        subject:
            currentClass.subject,

        date: dateString,

        classStart:
            currentClass.start,

        classEnd:
            currentClass.end,

        requiredFTF:
            currentClass.requiredFTF,

        entry_time: null,

        exit_time: null,

        duration: null,

        status: "ABSENT",

        reason: "",

        otherReason: ""

    };

}


// ==========================================
// GET RECORD
// ==========================================

let record =
    attendance[uid][sessionKey];


// ==========================================
// FIRST SCAN = ENTRY
// ==========================================

if (!record.entry_time) {

    record.entry_time =
        currentTime;

    record.status =
        "PRESENT";

}


// ==========================================
// ALREADY PRESENT
// RE-ENTRY DURING CLASS
// ==========================================

else if (
    record.entry_time &&
    !record.exit_time
) {

    node.warn(
        "STUDENT ALREADY PRESENT | ENTRY TIME KEPT: " +
        record.entry_time
    );

}


// ==========================================
// SESSION ALREADY COMPLETED
// ==========================================

else {

    node.warn(
        "ATTENDANCE SESSION ALREADY COMPLETED"
    );

}


// ==========================================
// SAVE ATTENDANCE
// ==========================================

flow.set(
    "attendanceRecords",
    attendance
);


// ==========================================
// SAVE TO HISTORY
// ==========================================

saveHistoryRecord(
    record,
    sessionKey
);


// ==========================================
// OUTPUT
// ATTENDANCE RECORD -> FTF CALCULATION
// ==========================================

msg.payload =
    record;

return msg;

// ==========================================
// MASTER TIMETABLE
// MULTI-LAB
// ==========================================

const timetable = [

    // ======================================
