    }

];


// ==========================================
// SAVE MASTER TIMETABLE
// ==========================================

flow.set(
    "masterTimetable",
    timetable
);


// ==========================================
// ALSO KEEP LAB 1 TIMETABLE
// FOR COMPATIBILITY
// ==========================================

flow.set(
    "lab1Timetable",
    timetable.filter(function (item) {
        return item.lab === "LAB 1";
    })
);


// ==========================================
// OUTPUT
// ==========================================

msg.payload = timetable;

return msg;

// ==========================================
// DASHBOARD DATA BUILDER
// MULTI-LAB
// STUDENT DATABASE = EXPECTED STUDENTS
// PRESENT + EXCUSED + ABSENT
// ==========================================

let currentData = msg.payload;


// ==========================================
// RESTORE CURRENT CLASS DATA
// ==========================================

if (
    !currentData ||
    !currentData.currentClasses ||
    !currentData.todaySchedule
) {

    currentData =
        flow.get("lastCurrentData");

    if (!currentData) {
        return null;
    }

}


// ==========================================
// SAVE LATEST CURRENT DATA
// ==========================================

flow.set(
    "lastCurrentData",
    currentData
);


// ==========================================
// GET STUDENT DATABASE
// ==========================================

let studentDatabase =
    flow.get("students") || [];


// ==========================================
// GET ATTENDANCE RECORDS
// ==========================================

let attendance =
    flow.get("attendanceRecords") || {};


// ==========================================
// GET ATTENDANCE FOR CURRENT LAB
// ==========================================

let _d = new Date();
let todayStr = _d.getFullYear() + "-" +
    String(_d.getMonth() + 1).padStart(2, "0") + "-" +
    String(_d.getDate()).padStart(2, "0");


function getAttendance(lab) {

    let presentCount = 0;

    let excusedCount = 0;

    let studentRecords = [];


    // ======================================
    // LOOP ALL ATTENDANCE RECORDS
    // ======================================

    for (
        let uid in attendance
    ) {

        let studentSessions =
            attendance[uid];


        if (
            !studentSessions ||
            typeof studentSessions !== "object"
        ) {

            continue;

        }


        // ==================================
        // LOOP STUDENT SESSIONS
        // ==================================

        for (
            let key in studentSessions
        ) {

            let record =
                studentSessions[key];


            if (!record) {
                continue;
            }


            // ==================================
            // MATCH LAB + SUBJECT + SEMESTER
            // ==================================

            if (
                record.date === todayStr &&
                record.lab === lab.lab &&
                record.subject === lab.subject &&
                record.className === lab.className &&
                record.classStart === lab.start &&
                record.classEnd === lab.end
            ) {


                // ==============================
                // PRESENT
                // ==============================

                if (
                    record.status === "PRESENT" &&
                    record.entry_time &&
                    record.entry_time !== "-"
                ) {

                    presentCount++;

                    studentRecords.push(
                        record
                    );

                }


                // ==============================
                // EXCUSED / MC
                // ==============================

                else if (
                    record.status === "EXCUSED" ||
                    record.status === "MC"
                ) {

                    // Count EXCUSED
                    // for ABSENT calculation

                    excusedCount++;


                    // IMPORTANT:
                    // DO NOT push EXCUSED
                    // into Main Dashboard
                }

            }

        }

    }


    return {

        present:
            presentCount,

        excused:
            excusedCount,

        students:
            studentRecords

    };

}


// ==========================================
// BUILD LAB DATA
// ==========================================

function buildLabData(
    lab,
    status
) {


    // ======================================
    // GET ATTENDANCE
    // ======================================

    let attendanceData =
        getAttendance(lab);


    let presentCount =
        attendanceData.present;


    let excusedCount =
        attendanceData.excused;


    // ======================================
    // COUNT STUDENTS FROM SQLITE DATABASE
    // ======================================

    let classStudents =
        studentDatabase.filter(
            function (student) {

                return (
                    student.semester ===
                    lab.className
                );

            }
        );


    // ======================================
    // EXPECTED STUDENTS
    // FROM STUDENT DATABASE
    // ======================================

    let expectedStudents =
        classStudents.length;


    // ======================================
    // ABSENT
    // ======================================

    let absentCount =
        expectedStudents -
        presentCount -
        excusedCount;


    if (
        absentCount < 0
    ) {

        absentCount = 0;

    }


    // ======================================
    // RETURN LAB DATA
    // ======================================

    return {

        lab:
            lab.lab,

        subject:
            lab.subject,

        className:
            lab.className,

        start:
            lab.start,

        end:
            lab.end,


        // ==================================
        // STUDENT DATABASE COUNT
        // ==================================

        expectedStudents:
            expectedStudents,


        // ==================================
        // ATTENDANCE COUNTS
        // ==================================

        presentStudents:
            presentCount,

        absentStudents:
            absentCount,


        // EXCUSED IS USED FOR
        // CALCULATION ONLY
        excusedStudents:
            excusedCount,


        requiredFTF:
            lab.requiredFTF,

        status:
            status,


        // ==================================
        // PRESENT STUDENTS ONLY
        // ==================================

        students:
            attendanceData.students

    };

}


