// ==========================================
// SESSION KEY
// Same date + lab + subject + class + time
// ==========================================

function sessionKey(s) {
    return [
        s.date || "",
        s.lab || "",
        s.subject || "",
        s.className || "",
        s.start || s.classStart || "",
        s.end || s.classEnd || ""
    ].join("|");
}

// ==========================================
// MERGE STUDENT WITHOUT LOSING VALID TIMES
// ==========================================

function mergeStudent(list, incoming) {
    if (!incoming || !incoming.uid) return;

    let index = list.findIndex(s => s.uid === incoming.uid);

    if (index < 0) {
        list.push({
            ...incoming,
            name: incoming.name || incoming.student || incoming.uid,
            entry_time: incoming.entry_time || "-",
            exit_time: incoming.exit_time || "-",
            duration: incoming.duration || "-",
            reason: incoming.reason || "",
            otherReason: incoming.otherReason || ""
        });
        return;
    }

    let old = list[index];

    // A real attendance entry takes priority.
    let oldHasEntry =
        old.entry_time && old.entry_time !== "-";

    let newHasEntry =
        incoming.entry_time && incoming.entry_time !== "-";

    let merged = {
        ...old,
        ...incoming,
        uid: incoming.uid,
        name: incoming.name || incoming.student || old.name || incoming.uid,
        entry_time: newHasEntry ? incoming.entry_time : (old.entry_time || "-"),
        exit_time: (incoming.exit_time && incoming.exit_time !== "-")
            ? incoming.exit_time : (old.exit_time || "-"),
        duration: (incoming.duration && incoming.duration !== "-")
            ? incoming.duration : (old.duration || "-"),
        reason: incoming.reason || old.reason || "",
        otherReason: incoming.otherReason || old.otherReason || ""
    };

    // Do not replace a genuine PRESENT record with EXCUSED/ABSENT.
    if (oldHasEntry) {
        merged.status = "PRESENT";
    } else if (newHasEntry) {
        merged.status = "PRESENT";
    } else if (
        old.status === "EXCUSED" || old.status === "MC" ||
        incoming.status === "EXCUSED" || incoming.status === "MC"
    ) {
        merged.status = "EXCUSED";
    } else {
        merged.status = incoming.status || old.status || "ABSENT";
    }

    list[index] = merged;
}

// ==========================================
// ADD / MERGE A SESSION
// ==========================================

function addSession(session) {
    if (
        !session ||
        !session.date ||
        !session.lab ||
        !session.subject ||
        !session.className
    ) return;

    let key = sessionKey(session);

    if (!sessions[key]) {
        sessions[key] = {
            date: session.date,
            lab: session.lab,
            subject: session.subject,
            className: session.className,
            start: session.start || session.classStart || "",
            end: session.end || session.classEnd || "",
            students: []
        };
    }

    let target = sessions[key];

    if (Array.isArray(session.students)) {
        session.students.forEach(student => mergeStudent(target.students, student));
    }
}

