function findFTFRecord(student, subject) {

    let exactKey = String(student.uid) + "_" + subject;

    // 1. Exact UID match
    if (ftfRecords[exactKey]) {
        return ftfRecords[exactKey];
    }

    // 2. Legacy UID fallback using student name + subject
    let studentName = normalize(student.name);
    let normalizedSubject = normalize(subject);

    for (let key of Object.keys(ftfRecords)) {

        let record = ftfRecords[key] || {};

        let recordSubject = normalize(
            record.subject || key.substring(key.indexOf("_") + 1)
        );

        let recordName = normalize(
            record.student ||
            record.studentName ||
            record.name
        );

        if (
            recordName === studentName &&
            recordSubject === normalizedSubject
        ) {
            return record;
        }
    }

    return {};
}

