// BUILD STUDENT DATA
// ==========================================

let studentData = students
    .filter(function(student) {
        return student && student.uid && student.name;
    })
    .map(function(student) {

        let studentSemester = normalizeSemester(student.semester);
        let subjectList = [];

        timetable.forEach(function(item) {

            if (!item) return;

            let timetableSemester = normalizeSemester(
                item.className || item.semester
            );

            if (timetableSemester === studentSemester) {

                let subject = String(item.subject || "").trim();

                if (
                    subject &&
                    !subjectList.some(function(existing) {
                        return normalize(existing) === normalize(subject);
                    })
                ) {
                    subjectList.push(subject);
                }
            }
        });

        let subjectData = subjectList.map(function(subject) {

            let ftf = findFTFRecord(student, subject);

            let requiredHours = Number(
                ftf.requiredHours ?? 80
            );

            let totalSeconds = Number(
                ftf.completedSeconds || 0
            );

            let completedHours = Number(
                ftf.completedHours ??
                Math.floor(totalSeconds / 3600)
            );

            let completedMinutes = Number(
                ftf.completedMinutes ??
                Math.floor((totalSeconds % 3600) / 60)
            );

            let completedTotal =
                completedHours + completedMinutes / 60;

            let remainingTotal = Math.max(
                0,
                requiredHours - completedTotal
            );

            let remainingHours = Math.floor(remainingTotal);

            let remainingMinutes = Math.round(
                (remainingTotal - remainingHours) * 60
            );

            let percentage = requiredHours > 0
                ? Math.min(
                    100,
                    Math.round(
                        (completedTotal / requiredHours) * 100
                    )
                )
                : 0;

            return {
                subject: subject,
                requiredHours: requiredHours,
                completedHours: completedHours,
                completedMinutes: completedMinutes,
                remainingHours: remainingHours,
                remainingMinutes: remainingMinutes,
                percentage: percentage,
                status: completedTotal >= requiredHours
                    ? "REQUIREMENT MET"
                    : "INCOMPLETE"
            };
        });

        return {
            uid: student.uid,
            name: student.name,
            semester: student.semester,
            status: student.status || "ACTIVE",
            subjects: subjectData
        };
    });

