function cleanText(value, field) {
    const result = String(value ?? "").trim();
    if (!result) throw new Error("Please fill in " + field);
    return result;
}

function cleanTime(value, field) {
    let raw = String(value ?? "").trim();

    if (raw.includes("T")) {
        raw = raw.split("T")[1] || "";
    }

    const match = raw.match(/^(\d{1,2}):(\d{2})(?::\d{2})?/);
    if (!match) throw new Error("Invalid time: " + field);

    const hours = Number(match[1]);
    const minutes = Number(match[2]);

    if (hours > 23 || minutes > 59) {
        throw new Error("Invalid time: " + field);
    }

    return String(hours).padStart(2, "0") + ":" +
        String(minutes).padStart(2, "0");
}

function cleanNumber(value, field) {
    if (value === "" || value === null || value === undefined) {
        return 0;
    }

    const number = Number(value);
    if (!Number.isFinite(number) || number < 0) {
        throw new Error("Invalid number: " + field);
    }

    return number;
}

function validId(value) {
    const id = Number(value);
    if (!Number.isInteger(id) || id < 1) {
        throw new Error("Invalid schedule record ID");
    }
    return id;
}

